// insert_ui_component: the ONLY way Apple puts game UI in a place (D-UIONLY-1).
//
// Every visible pixel is a stored library file. The component catalogue
// (packages/asset-library/ui-components.json, generated by build-ui-components.mjs) says which
// file plays which role in which genre skin, with the 9-slice margins, text ink and outline colour
// measured off the PNG and the font taken from the sources list. This module only arranges those
// pieces: it emits transparent layout frames, ImageLabels/ImageButtons whose Image is an uploaded
// library file, and TextLabels whose colour is a sampled library pixel. It never names a colour,
// an image or a font of its own.
//
// Image ids come from, in order: the shared table packages/asset-library/roblox-ids.json, the
// user's own cache (KV), then an upload of the stored file into the user's own Roblox account
// (uploadLibraryAsset, their key, Robux ceiling 0). An image that cannot be resolved stops the
// insert: a component with a blank square where its panel should be is not inserted.
import lib from '../../../packages/asset-library/ui-components.json';
import shared from '../../../packages/asset-library/roblox-ids.json';
import type { GatewayToolDef, InstanceSpec, PropValue, StudioOp } from '@golem/shared';
import type { Env } from './env';
import type { LibraryRule } from './library-guard';
import type { OpCall } from './phase-a-tools';
import { libraryAsset, uploadLibraryAsset, type UploadDeps } from './asset-library';
import { uiStoreImage } from './ui-store-search';

type Spec = Omit<InstanceSpec, 'parent'>;
type P = Record<string, PropValue>;
type Args = Record<string, unknown>;
interface Img { w: number; h: number; slice: number[]; centre: number[]; edge: number[]; text: 'light' | 'dark' }
interface Skin { title: string; genres: string[]; font: string; colours: string[]; roles: Record<string, Record<string, string>> }
interface Component { id: string; title: string; group: string; genres: string[]; roles: string[]; icons: string[] }
interface Lib { ink: { ink_light: number[]; ink_dark: number[] }; skins: Record<string, Skin>; icons: Record<string, string>; images: Record<string, Img>; components: Component[] }

const L = lib as unknown as Lib;
const SHARED_IDS = (shared as unknown as { ids: Record<string, string> }).ids;
const COMPONENTS = new Map(L.components.map((c) => [c.id, c]));
export const UI_COMPONENT_IDS = L.components.map((c) => c.id);
const GENRE_OF = new Map<string, string>();
for (const [id, s] of Object.entries(L.skins)) { GENRE_OF.set(id, id); for (const g of s.genres) GENRE_OF.set(g, id); }
const ANCHORS = ['top_left', 'top', 'top_right', 'left', 'center', 'right', 'bottom_left', 'bottom', 'bottom_right'] as const;
type Anchor = (typeof ANCHORS)[number];
const ANCHOR_POINTS: Record<Anchor, [number, number]> = {
  top_left: [0, 0], top: [0.5, 0], top_right: [1, 0], left: [0, 0.5], center: [0.5, 0.5], right: [1, 0.5],
  bottom_left: [0, 1], bottom: [0.5, 1], bottom_right: [1, 1],
};
const MARGIN = 0.02;
const WORLD = new Set(['billboard_tag', 'surface_sign']);

/* ------------------------------------------------------------------ wire values --- */

const udim2 = (xs: number, xo: number, ys: number, yo: number): PropValue => ({ t: 'UDim2', v: [xs, xo, ys, yo] }) as PropValue;
const udim = (s: number, o: number): PropValue => ({ t: 'UDim', v: [s, o] }) as PropValue;
const vec2 = (x: number, y: number): PropValue => ({ t: 'Vector2', v: [x, y] }) as PropValue;
const vec3 = (x: number, y: number, z: number): PropValue => ({ t: 'Vector3', v: [x, y, z] }) as PropValue;
const num = (v: number): PropValue => ({ t: 'number', v }) as PropValue;
const bool = (v: boolean): PropValue => ({ t: 'bool', v }) as PropValue;
const str = (v: string): PropValue => ({ t: 'string', v }) as PropValue;
const enumItem = (v: string): PropValue => ({ t: 'EnumItem', v }) as PropValue;
const rect = (r: number[]): PropValue => ({ t: 'Rect', v: r }) as PropValue;
const rgb = (c: number[]): PropValue => ({ t: 'Color3', v: c.map((x) => Math.round((x / 255) * 1000) / 1000) }) as PropValue;
const r3 = (n: number) => Math.round(n * 1000) / 1000;
const at = (xs: number, ys: number, ax = 0, ay = 0): P => ({ Position: udim2(xs, 0, ys, 0), AnchorPoint: vec2(ax, ay) });
const sized = (w: number, h: number): P => ({ Size: udim2(w, 0, h, 0) });
const box = (x: number, y: number, w: number, h: number, ax = 0, ay = 0): P => ({ ...at(x, y, ax, ay), ...sized(w, h) });

/* --------------------------------------------------------------------- builder --- */

interface Item { name?: string; value?: number | string | boolean; price?: number | string; icon?: string; locked?: boolean; kind?: string; options?: string[] }
interface Input {
  component: Component; skin: string; colour: string; name: string;
  title?: string; text?: string; value?: number | string | boolean; items?: Item[]; icon?: string;
}

class Builder {
  count = 0;
  readonly assets = new Set<string>();
  readonly roles: Record<string, string>;
  readonly font: string;
  constructor(readonly input: Input, readonly idOf: (asset: string) => string) {
    const s = L.skins[input.skin]!;
    this.roles = s.roles[input.colour]!;
    this.font = s.font;
  }

  spec(className: string, name: string, props: P, children: Spec[] = []): Spec {
    this.count += 1;
    return children.length ? { className, name, props, children } : { className, name, props };
  }
  frame(name: string, place: P, children: Spec[] = []): Spec {
    return this.spec('Frame', name, { ...place, BackgroundTransparency: num(1) }, children);
  }
  aspect(ratio: number): Spec {
    return this.spec('UIAspectRatioConstraint', 'Aspect', { AspectRatio: num(r3(ratio)) });
  }
  role(role: string): string {
    const asset = this.roles[role];
    if (!asset) throw new Error(`${this.input.component.id} used role ${role}, which skin ${this.input.skin} does not have`);
    return asset;
  }
  picture(asset: string): P {
    this.assets.add(asset);
    return { Image: str(`rbxassetid://${this.idOf(asset)}`), BackgroundTransparency: num(1) };
  }
  /** A 9-slice library image, stretched to `place` without distorting its corners. */
  slice(name: string, role: string, place: P, children: Spec[] = [], button = false): Spec {
    const asset = this.role(role);
    return this.spec(button ? 'ImageButton' : 'ImageLabel', name, {
      ...place, ...this.picture(asset),
      ScaleType: enumItem('Enum.ScaleType.Slice'), SliceCenter: rect(L.images[asset]!.slice),
    }, children);
  }
  /** A library image drawn whole at its own aspect (icons, round buttons, rings). */
  fit(name: string, asset: string, place: P, children: Spec[] = [], button = false): Spec {
    return this.spec(button ? 'ImageButton' : 'ImageLabel', name, { ...place, ...this.picture(asset), ScaleType: enumItem('Enum.ScaleType.Fit') }, children);
  }
  icon(name: string, key: string, place: P): Spec {
    return this.fit(name, iconAsset(key)!, place);
  }
  /** Text in the skin's font, inked for the surface it sits on (the surface's own measured verdict). */
  label(name: string, text: string, on: string | null, place: P, max = 30): Spec {
    const surface = on ? L.images[on]! : null;
    const light = !surface || surface.text === 'light';
    return this.spec('TextLabel', name, {
      ...place,
      BackgroundTransparency: num(1),
      Text: str(text),
      Font: enumItem(this.font),
      TextColor3: rgb(light ? L.ink.ink_light : L.ink.ink_dark),
      TextScaled: bool(true),
      TextWrapped: bool(true),
      ...(light ? { TextStrokeTransparency: num(0), TextStrokeColor3: rgb(surface ? surface.edge : L.ink.ink_dark) } : {}),
    }, [this.spec('UITextSizeConstraint', 'TextLimit', { MinTextSize: num(10), MaxTextSize: num(max) })]);
  }

  /* -------- shared pieces -------- */

  /** A chip: rounded pill with an icon on the left and one line of text. */
  chip(name: string, iconKey: string, text: string, place: P): Spec {
    const chip = this.role('chip');
    return this.slice(name, 'chip', place, [
      this.icon('Icon', iconKey, box(0.04, 0.5, 0.26, 0.8, 0, 0.5)),
      this.label('Value', text, chip, box(0.32, 0.5, 0.64, 0.7, 0, 0.5)),
    ]);
  }
  button(name: string, role: 'button_primary' | 'button_secondary', text: string, place: P, iconKey?: string): Spec {
    const asset = this.role(role);
    const kids = iconKey
      ? [this.icon('Icon', iconKey, box(0.06, 0.5, 0.22, 0.7, 0, 0.5)), this.label('Label', text, asset, box(0.3, 0.5, 0.64, 0.62, 0, 0.5))]
      : [this.label('Label', text, asset, box(0.5, 0.5, 0.86, 0.62, 0.5, 0.5))];
    return this.slice(name, role, place, kids, true);
  }
  bar(name: string, fillRole: 'bar_fill' | 'bar_health', value: number, text: string | null, place: P): Spec {
    const track = this.role('bar_track');
    const v = Math.max(0, Math.min(1, value));
    return this.slice(name, 'bar_track', place, [
      this.slice('Fill', fillRole, box(0, 0, v, 1)),
      ...(text !== null ? [this.label('Value', text, track, box(0.5, 0.5, 0.9, 0.7, 0.5, 0.5))] : []),
    ]);
  }
  close(place: P): Spec {
    const asset = this.role('button_close');
    // Some packs draw the X into the close button itself; only a plain button gets the cross icon.
    const drawn = /close|cross/i.test(asset.slice(asset.lastIndexOf('/')));
    return this.fit('Close', asset, place, [...(drawn ? [] : [this.icon('Icon', 'cross', box(0.5, 0.45, 0.5, 0.5, 0.5, 0.5))]), this.aspect(1)], true);
  }
  /** Panel + header title (+ optional header icon) + close button; `content` fills the body. */
  window(title: string, content: Spec[], opts: { close?: boolean; headerIcon?: string } = {}): Spec {
    const header = this.role('header');
    const head = this.slice('Header', 'header', box(0.5, 0.025, 0.62, 0.13, 0.5, 0), [
      ...(opts.headerIcon ? [this.icon('Icon', opts.headerIcon, box(0.05, 0.5, 0.14, 0.78, 0, 0.5))] : []),
      this.label('Title', title, header, opts.headerIcon ? box(0.2, 0.5, 0.74, 0.7, 0, 0.5) : box(0.5, 0.5, 0.9, 0.7, 0.5, 0.5), 40),
    ]);
    return this.slice(this.input.name, 'panel', {}, [
      head,
      ...(opts.close === false ? [] : [this.close(box(0.975, 0.025, 0.1, 0.13, 1, 0))]),
      this.frame('Content', box(0.5, 0.19, 0.9, 0.77, 0.5, 0), content),
    ]);
  }
  /** A scrolling grid of cells, three across, two rows visible. */
  grid(cells: Spec[], cols = 3, visibleRows = 2): Spec {
    const rows = Math.max(visibleRows, Math.ceil(cells.length / cols));
    return this.spec('ScrollingFrame', 'Grid', {
      ...box(0, 0, 1, 1), BackgroundTransparency: num(1), BorderSizePixel: num(0), ScrollBarThickness: num(6),
      CanvasSize: udim2(0, 0, r3(rows / visibleRows), 0),
    }, [
      this.spec('UIGridLayout', 'Layout', {
        CellSize: udim2(r3(0.94 / cols), 0, r3(0.9 / rows), 0), CellPadding: udim2(r3(0.05 / cols), 0, r3(0.08 / rows), 0),
        SortOrder: enumItem('Enum.SortOrder.LayoutOrder'), HorizontalAlignment: enumItem('Enum.HorizontalAlignment.Center'),
      }),
      ...cells,
    ]);
  }
  /** Rows stacked top to bottom. */
  rows(children: Spec[], gap = 0.02): Spec {
    return this.frame('Rows', box(0, 0, 1, 1), [
      this.spec('UIListLayout', 'Layout', {
        FillDirection: enumItem('Enum.FillDirection.Vertical'), HorizontalAlignment: enumItem('Enum.HorizontalAlignment.Center'),
        SortOrder: enumItem('Enum.SortOrder.LayoutOrder'), Padding: udim(gap, 0),
      }),
      ...children.map((c, i) => ({ ...c, props: { ...c.props, LayoutOrder: num(i + 1) } })),
    ]);
  }
  toggle(name: string, on: boolean, place: P): Spec {
    const onA = this.role('toggle_on');
    const offA = this.role('toggle_off');
    this.picture(onA); this.picture(offA);
    const t = this.fit(name, on ? onA : offA, place, [], true);
    // A script flips it with btn.Image = btn:GetAttribute(on and "OnImage" or "OffImage"): both
    // states stay library files, and the script never names an image.
    t.attributes = { OnImage: str(`rbxassetid://${this.idOf(onA)}`), OffImage: str(`rbxassetid://${this.idOf(offA)}`), On: bool(on) };
    return t;
  }
  slider(name: string, value: number, place: P): Spec {
    const v = Math.max(0, Math.min(1, value));
    return this.slice(name, 'slider_track', place, [
      this.fit('Handle', this.role('slider_handle'), box(v, 0.5, 1.6, 1.6, 0.5, 0.5), [this.aspect(1)], true),
    ]);
  }
  dropdown(name: string, options: string[], selected: number, place: P): Spec {
    const input = this.role('input');
    return this.slice(name, 'input', place, [
      this.label('Value', options[selected] ?? options[0] ?? '', input, box(0.06, 0.5, 0.7, 0.62, 0, 0.5)),
      this.fit('Arrow', this.role('dropdown_arrow'), box(0.95, 0.5, 0.16, 0.6, 1, 0.5), [this.aspect(1)], true),
      this.frame('Options', { ...box(0, 1.05, 1, options.length, 0, 0), Visible: bool(false) }, [
        this.spec('UIListLayout', 'Layout', { FillDirection: enumItem('Enum.FillDirection.Vertical'), SortOrder: enumItem('Enum.SortOrder.LayoutOrder') }),
        ...options.map((o, i) => this.slice(`Option${i + 1}`, 'input', { ...sized(1, r3(1 / options.length)), LayoutOrder: num(i + 1) }, [
          this.label('Label', o, input, box(0.06, 0.5, 0.88, 0.62, 0, 0.5)),
        ], true)),
      ]),
    ]);
  }
}

/* ------------------------------------------------------------------- components --- */

const n = (v: unknown, d: number): number => (typeof v === 'number' && Number.isFinite(v) ? v : d);
const s = (v: unknown, d: string): string => (typeof v === 'string' && v.length ? v : typeof v === 'number' ? String(v) : d);
const items = (a: Input, d: Item[]): Item[] => (a.items && a.items.length ? a.items : d);

