/* ------------------------------------------------------------------ arguments --- */

function iconAsset(key: string): string | null {
  if (L.icons[key]) return L.icons[key]!;
  // Any other library file may stand in for an icon, but only one the index names — a CC0 pack
  // file, or a Creator Store image already on Roblox (D-UISTORE-1).
  return libraryAsset(key)?.asset ?? uiStoreImage(key)?.image ?? null;
}

export interface Compiled {
  component: Component;
  skin: string;
  colour: string;
  name: string;
  world: boolean;
  item: Spec;
  assets: string[];
  count: number;
  size: [number, number];
  anchor: Anchor;
}

const refuse = (message: string) => ({ error: `${message} Nothing was sent to Studio.` });

function readInput(a: Args): Input | { error: string } {
  const component = COMPONENTS.get(String(a.component ?? ''));
  if (!component) return refuse(`component must be one of: ${UI_COMPONENT_IDS.join(', ')}.`);
  const genre = String(a.genre ?? '').toLowerCase().trim();
  const skin = GENRE_OF.get(genre);
  if (!skin) return refuse(`genre "${genre}" has no skin; use one of: ${[...GENRE_OF.keys()].join(', ')}.`);
  if (!component.genres.includes(skin)) {
    return refuse(`${component.id} is not in the ${skin} skin (it is in ${component.genres.join(', ')}). Use another component or genre.`);
  }
  const colours = L.skins[skin]!.colours;
  const colour = a.colour === undefined ? colours[0]! : String(a.colour).toLowerCase();
  if (!colours.includes(colour)) return refuse(`colour must be one of ${colours.join(', ')} for the ${skin} skin.`);
  const name = a.name === undefined ? component.id.split('_').map((w) => w[0]!.toUpperCase() + w.slice(1)).join('') : String(a.name);
  if (!/^[A-Za-z][A-Za-z0-9_]{0,49}$/.test(name)) return refuse('name must be 1-50 letters, digits or _, starting with a letter.');
  const text = (v: unknown, label: string, max: number): string | undefined | { error: string } => {
    if (v === undefined) return undefined;
    if (typeof v !== 'string' && typeof v !== 'number') return refuse(`${label} must be text.`);
    const t = String(v);
    return t.length > max ? refuse(`${label} is longer than ${max} characters.`) : t;
  };
  const title = text(a.title, 'title', 40);
  const body = text(a.text, 'text', 120);
  for (const t of [title, body]) if (t && typeof t === 'object') return t;
  if (a.icon !== undefined && !iconAsset(String(a.icon))) return refuse(`icon must be one of ${Object.keys(L.icons).join(', ')}, or a library asset from find_ui_asset.`);
  let list: Item[] | undefined;
  if (a.items !== undefined) {
    if (!Array.isArray(a.items) || a.items.length > 12) return refuse('items must be a list of at most 12 entries.');
    list = [];
    for (const [i, raw] of a.items.entries()) {
      const it: Item = typeof raw === 'string' || typeof raw === 'number' ? { name: String(raw) } : raw && typeof raw === 'object' ? { ...(raw as Item) } : {};
      if (it.name !== undefined && String(it.name).length > 40) return refuse(`items[${i}].name is longer than 40 characters.`);
      if (it.icon !== undefined && !iconAsset(String(it.icon))) return refuse(`items[${i}].icon must be one of ${Object.keys(L.icons).join(', ')}, or a library asset from find_ui_asset.`);
      if (it.options !== undefined && (!Array.isArray(it.options) || it.options.length > 8)) return refuse(`items[${i}].options must be at most 8 strings.`);
      list.push(it);
    }
    if (component.id === 'mobile_action_buttons') {
      for (const [i, it] of list.entries()) if (!iconAsset(s(it.icon ?? it.name, ''))) return refuse(`items[${i}] must name an icon (${Object.keys(L.icons).join(', ')}).`);
    }
  }
  const value = a.value;
  if (value !== undefined && !['number', 'string', 'boolean'].includes(typeof value)) return refuse('value must be a number, text or true/false.');
  return {
    component, skin, colour, name,
    title: title as string | undefined, text: body as string | undefined,
    value: value as Input['value'], items: list, icon: a.icon === undefined ? undefined : String(a.icon),
  };
}

function vecArg(v: unknown, label: string, lo: number): [number, number] | undefined | { error: string } {
  if (v === undefined) return undefined;
  if (!Array.isArray(v) || v.length !== 2 || !v.every((x) => typeof x === 'number' && x >= lo && x <= 1)) return refuse(`${label} must be [x, y], two fractions of the screen from ${lo} to 1.`);
  return v as [number, number];
}

/** Arguments -> one create_instances item (no parent yet), or what is wrong. `idOf` maps a library file to its Roblox id. */
export function compileComponent(a: Args, idOf: (asset: string) => string = () => '0'): Compiled | { error: string } {
  const input = readInput(a);
  if ('error' in input) return input;
  const recipe = BUILD[input.component.id]!;
  const size = vecArg(a.size, 'size', 0.02);
  if (size && 'error' in size) return size;
  const position = vecArg(a.position, 'position', 0);
  if (position && 'error' in position) return position;
  const anchor = (a.anchor === undefined ? recipe.anchor : String(a.anchor)) as Anchor;
  if (!ANCHORS.includes(anchor)) return refuse(`anchor must be one of ${ANCHORS.join(', ')}.`);
  const b = new Builder(input, idOf);
  const root = recipe.build(b, input);
  const world = WORLD.has(input.component.id);
  if (!world) {
    const [w, h] = (size as [number, number] | undefined) ?? recipe.size;
    const [ax, ay] = ANCHOR_POINTS[anchor];
    const [px, py] = (position as [number, number] | undefined) ?? [ax === 0 ? MARGIN : ax === 1 ? 1 - MARGIN : 0.5, ay === 0 ? MARGIN : ay === 1 ? 1 - MARGIN : 0.5];
    root.props = { ...root.props, ...box(px, py, w, h, ax, ay) };
    // The component keeps the shape it was drawn at on a 16:9 screen, whatever the device.
    if (!(w === 1 && h === 1) && !root.children?.some((c) => c.className === 'UIAspectRatioConstraint')) {
      root.children = [...(root.children ?? []), b.aspect((w * 16) / (h * 9))];
    }
  }
  return {
    component: input.component, skin: input.skin, colour: input.colour, name: input.name, world,
    item: root, assets: [...b.assets].sort(), count: b.count,
    size: (size as [number, number] | undefined) ?? recipe.size, anchor,
  };
}

/* --------------------------------------------------------------- image ids --- */

export type ResolveIds = (assets: string[]) => Promise<{ ids: Record<string, string>; missing: { asset: string; why: string }[] }>;

/** Shared table, then the user's cache, then an upload into the user's own account. */
export function uiImageResolver(env: Env, userId: string | undefined, deps: UploadDeps = {}): ResolveIds {
  return async (assets) => {
    const ids: Record<string, string> = {};
    const missing: { asset: string; why: string }[] = [];
    await Promise.all(assets.map(async (asset) => {
      if (SHARED_IDS[asset]) { ids[asset] = SHARED_IDS[asset]!; return; }
      // A Creator Store image is on Roblox already: its id is set as it is, never uploaded.
      const store = uiStoreImage(asset);
      if (store) { ids[asset] = String(store.imageId); return; }
      const key = userId ? `ui-image:${userId}:${asset}` : null;
      const cached = key ? await env.KV?.get(key).catch(() => null) : null;
      if (cached && /^\d+$/.test(cached)) { ids[asset] = cached; return; }
      const up = await uploadLibraryAsset(env, userId, { asset }, deps);
      if (typeof up.assetId === 'string' || typeof up.assetId === 'number') {
        ids[asset] = String(up.assetId);
        if (key) await env.KV?.put(key, ids[asset]!).catch(() => undefined);
        return;
      }
      missing.push({ asset, why: String(up.error ?? up.note ?? 'no id yet') });
    }));
    return { ids, missing };
  };
}

/* -------------------------------------------------------------------- the tool --- */

const GUI_CONTAINERS = new Set(['ScreenGui', 'Frame', 'ImageLabel', 'ImageButton', 'ScrollingFrame', 'CanvasGroup', 'SurfaceGui', 'BillboardGui']);

export const insertUiComponent = {
  def: {
    name: 'insert_ui_component',
    description:
      'The ONLY way to put game UI in the place (D-UIONLY-1): inserts one ready-made component from Apple\'s UI library, drawn entirely from stored library images (9-slice panels, buttons, bars, icons) in a genre skin, with the skin\'s font. ' +
      `component: ${UI_COMPONENT_IDS.join(', ')}. genre picks the skin: simulator/tycoon/clicker/pet, obby/parkour/tower, adventure/horror/rpg/survival, shooter/fps/fighting. ` +
      'colour picks the skin colour; title/text/value/items fill it in (items: strings, or {name, value, price, icon, locked, kind: toggle|slider|dropdown, options}); icon is an icon key (coin, gem, star, heart, gear, trophy, cart, lock, timer, rebirth, quest, key, gift, crown, sword, shield, jump, target, pet, ...). ' +
      'Without parent it becomes a new ScreenGui named `name` in StarterGui; parent may be an existing ScreenGui/Frame to nest it. billboard_tag and surface_sign need parent = the part. anchor/position/size are screen fractions. ' +
      'Afterwards change text/position/visibility with set_properties; wire behaviour in a LocalScript that finds the inserted instances by path. Creating Frames, buttons, labels or images any other way is refused.',
    parameters: {
      type: 'object',
      properties: {
        component: { type: 'string', enum: UI_COMPONENT_IDS },
        genre: { type: 'string', description: 'the game genre, e.g. simulator, obby, horror, shooter' },
        colour: { type: 'string', description: 'a colour of the skin (simulator/obby/shooter: green, blue, yellow, red; adventure: brown, grey)' },
        name: { type: 'string', description: 'instance name, e.g. "ShopGui"; must be free where it goes' },
        parent: { type: 'string', description: 'existing ScreenGui/Frame path to nest into, or the part for billboard_tag/surface_sign' },
        title: { type: 'string' },
        text: { type: 'string' },
        value: { description: 'number (bars 0-1, counters), text, or true/false (toggle)' },
        items: { type: 'array', maxItems: 12, items: {} },
        icon: { type: 'string' },
        anchor: { type: 'string', enum: [...ANCHORS] },
        position: { type: 'array', items: { type: 'number' }, minItems: 2, maxItems: 2 },
        size: { type: 'array', items: { type: 'number' }, minItems: 2, maxItems: 2 },
      },
      required: ['component', 'genre'],
    },
  } satisfies GatewayToolDef,

  run: async (call: OpCall, a: Args, resolve: ResolveIds): Promise<unknown> => {
    const plan = compileComponent(a);
    if ('error' in plan) return plan;
    const parent = a.parent === undefined ? null : String(a.parent).trim();
    if (parent !== null && !/^[A-Za-z0-9_.]+$/.test(parent)) return refuse(`"${parent}" is not an instance path.`);
    if (plan.world && !parent) return refuse(`${plan.component.id} goes on a part: pass parent, e.g. "game.Workspace.Shop.Sign".`);

    // Where it goes is checked before anything is uploaded or built.
    if (parent) {
      const where = await call({ op: 'get_instance', path: parent });
      const cls = where && typeof where === 'object' && !('error' in where) ? String((where as Args).class ?? '') : null;
      if (cls === null) return { ...(where as object), note: `Could not read ${parent}, so nothing was built.` };
      if (!plan.world && !GUI_CONTAINERS.has(cls)) return refuse(`${parent} is a ${cls}; a screen component nests only in ${[...GUI_CONTAINERS].join(', ')}. Leave parent out to make a new ScreenGui.`);
      if (plan.world && GUI_CONTAINERS.has(cls)) return refuse(`${parent} is a ${cls}; ${plan.component.id} goes on a part in the world.`);
      const clash = await call({ op: 'get_instance', path: `${parent}.${plan.name}` });
      const err = clash && typeof clash === 'object' && 'error' in clash ? String((clash as Args).error) : null;
      if (err === null) return refuse(`${parent}.${plan.name} already exists. Pick another name.`);
      if (!/\bnot found\b/i.test(err)) return { error: `Could not check whether ${parent}.${plan.name} is free (${err}), so nothing was built.` };
    } else {
      const existing = await call({ op: 'query_instances', root: 'game.StarterGui', className: 'ScreenGui', name: plan.name, limit: 50 });
      if (existing && typeof existing === 'object' && 'error' in existing) return { ...(existing as object), note: 'Could not check whether the screen name is free, so nothing was built.' };
      const taken = (((existing as Args).matches as Array<{ path?: unknown }> | undefined) ?? [])
        .some((m) => typeof m.path === 'string' && m.path.endsWith(`StarterGui.${plan.name}`));
      if (taken) return refuse(`game.StarterGui.${plan.name} already exists. Choose another name, or nest this component in it with parent.`);
    }

    const { ids, missing } = await resolve(plan.assets);
    if (missing.length) {
      return {
        error: `The component needs ${plan.assets.length} library images and ${missing.length} have no Roblox id yet, so nothing was built: ${missing.slice(0, 4).map((m) => `${m.asset} (${m.why})`).join('; ')}.`,
        missing: missing.map((m) => m.asset),
      };
    }
    const built = compileComponent(a, (asset) => ids[asset]!);
    if ('error' in built) return built;

    const full = !built.world && built.size[0] === 1 && built.size[1] === 1;
    const item: InstanceSpec = parent
      ? { ...built.item, parent }
      : {
        className: 'ScreenGui', name: built.name, parent: 'game.StarterGui',
        props: {
          ResetOnSpawn: bool(false), ZIndexBehavior: enumItem('Enum.ZIndexBehavior.Sibling'),
          ...(full ? { IgnoreGuiInset: bool(true), DisplayOrder: num(100) } : { ScreenInsets: enumItem('Enum.ScreenInsets.CoreUISafeInsets') }),
        },
        children: [built.item],
      };
    const made = await call({ op: 'create_instances', items: [item] } as StudioOp, 60_000);
    if (made && typeof made === 'object' && 'error' in made) return made;
    const created = (made as Args).created;
    const top = Array.isArray(created) && typeof created[0] === 'string' ? created[0] : parent ? `${parent}.${built.name}` : `game.StarterGui.${built.name}`;
    const root = parent ? top : `${top}.${built.name}`;
    const screen = parent ? (/^game\.StarterGui\.[A-Za-z0-9_]+/.exec(parent)?.[0] ?? null) : top;
    const layout = screen && !built.world ? await call({ op: 'ui_layout_check', screen }, 60_000) : null;
    return {
      inserted: root,
      component: built.component.id,
      skin: built.skin,
      colour: built.colour,
      instances: built.count + (parent ? 0 : 1),
      parts: partsOf(built.item, root),
      images: built.assets.map((asset) => ({ asset, id: ids[asset] })),
      projectMutated: true,
      ...(layout ? { layout: layout && typeof layout === 'object' && !('error' in layout) ? { verdict: (layout as Args).verdict, issues: (layout as Args).issues } : { notChecked: (layout as Args).error } } : {}),
      next: 'Change text, value and visibility with set_properties on the paths in `parts`; wire behaviour in a LocalScript that finds them by path. Toggles and tabs carry OnImage/OffImage attributes to swap Image with.',
      ...(made && typeof made === 'object' && 'propIssues' in made ? { propIssues: (made as Args).propIssues } : {}),
    };
  },
};

/** The paths a script or set_properties call needs: buttons, inputs, and the Value/Fill/Title pieces. */
function partsOf(root: Spec, rootPath: string): string[] {
  const out: string[] = [];
  const walk = (s: Spec, path: string) => {
    if (s.className === 'ImageButton' || s.className === 'TextBox' || ['Value', 'Fill', 'Title', 'Message', 'Body'].includes(s.name)) out.push(path);
    for (const c of s.children ?? []) walk(c, `${path}.${c.name}`);
  };
  walk(root, rootPath);
  return out.slice(0, 40);
}

/* ------------------------------------------------------------------ the rule --- */

/** GuiObjects, LayerCollectors and the styling objects that make a look: built by insert_ui_component only. */
export const UI_CLASSES: ReadonlySet<string> = new Set([
  'ScreenGui', 'SurfaceGui', 'BillboardGui', 'Frame', 'CanvasGroup', 'ScrollingFrame', 'TextLabel', 'TextButton', 'TextBox',
  'ImageLabel', 'ImageButton', 'ViewportFrame', 'VideoFrame', 'UIStroke', 'UICorner', 'UIGradient',
]);

const SUGGEST: Record<string, string> = {
  TextButton: 'button_primary', ImageButton: 'button_icon', TextLabel: 'stat_counter', ImageLabel: 'currency_counter', TextBox: 'codes_entry',
  ScrollingFrame: 'inventory_grid', BillboardGui: 'billboard_tag', SurfaceGui: 'surface_sign',
};

export const UI_RULE: LibraryRule = {
  decision: 'D-UIONLY-1',
  what: 'game UI',
  classes: UI_CLASSES,
  suggest: (cls) => {
    const id = SUGGEST[cls];
    if (cls === 'BillboardGui' || cls === 'SurfaceGui') return `insert_ui_component({"component":"${id}","genre":"<game genre>","parent":"<the part>"})`;
    if (id) return `insert_ui_component({"component":"${id}","genre":"<game genre>"})`;
    if (cls === 'UIStroke' || cls === 'UICorner' || cls === 'UIGradient') return 'nothing: a component\'s corners, outline and fill are its library images; pick another colour or genre skin in insert_ui_component instead';
    return `insert_ui_component({"component":"<one of ${UI_COMPONENT_IDS.join(', ')}>","genre":"<game genre>"})`;
  },
};

/** Properties that set how UI LOOKS. On inserted UI they come from the library, so they are not set by hand. */
export const UI_LOOK_PROPS: ReadonlySet<string> = new Set([
  'Image', 'HoverImage', 'PressedImage', 'ImageContent', 'ImageColor3', 'ImageRectOffset', 'ImageRectSize', 'SliceCenter', 'SliceScale', 'ScaleType', 'TileSize', 'ResampleMode',
  'BackgroundColor3', 'BorderColor3', 'TextColor3', 'TextStrokeColor3', 'PlaceholderColor3', 'Font', 'FontFace',
]);
const STYLE_CLASSES = new Set(['UIStroke', 'UICorner', 'UIGradient']);

/** A set_properties / set_properties_bulk that restyles UI by hand, or null. `className` when it is known. */
export function refuseUiLook(props: unknown, className?: string): { error: string } | null {
  if (!props || typeof props !== 'object') return null;
  const keys = Object.keys(props as object);
  const bad = className && STYLE_CLASSES.has(className) ? keys : keys.filter((k) => UI_LOOK_PROPS.has(k));
  if (!bad.length) return null;
  return {
    error:
      `Refused (D-UIONLY-1): ${bad.join(', ')} set how UI looks, and every look comes from the UI library. ` +
      'Pick a different colour or genre skin with insert_ui_component (and delete the old one); set_properties may still change Text, Position, Size, Visible, LayoutOrder and the like. Nothing was changed.',
  };
}
